import{_ as i,o as a,c as o,ag as r}from"./chunks/framework.IxO3mcwW.js";const s="/getbiji-docs/images/command-01.png",e="/getbiji-docs/images/command-02.png",l="/getbiji-docs/images/command-03.png",n="/getbiji-docs/images/command-04.png",d="/getbiji-docs/images/command-05.png",p="/getbiji-docs/images/command-06.png",f=JSON.parse('{"title":"语音口令","description":"","frontmatter":{},"headers":[],"relativePath":"voice/command.md","filePath":"voice/command.md","lastUpdated":1773215704000}'),c={name:"voice/command.md"};function m(g,t,h,_,u,b){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="语音口令" tabindex="-1">语音口令 <a class="header-anchor" href="#语音口令" aria-label="Permalink to &quot;语音口令&quot;">​</a></h1><blockquote><p>语音口令——录音中说句话，AI 帮你标记重点</p></blockquote><p>录音时说出口令词，AI 自动捕捉关键内容并特别处理</p><p>Get笔记全新推出语音口令功能，你可以自定义口令词和对应的处理要求。录音过程中，只需说出口令词，AI 就能自动识别并对相关内容做特别处理——标记重点、提炼金句、总结要点，动动嘴就能完成。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>课堂听讲</strong>：老师讲到重点时，说一句「帮我记一下」，AI 自动捕捉该知识点并总结，不用暂停、不用切 App、不用打字，2小时的课10分钟就能复习完</li><li><strong>读书思考</strong>：看到精彩段落念出来，说一句「这段不错」，手不离书、眼不离页面，看完后读书笔记自动整理好</li><li><strong>灵感捕捉</strong>：开车、通勤时突然冒出好想法，说一句「这个想法记一下」，到了目的地灵感全都在，不会再丢了</li><li><strong>听播客/音频节目</strong>：一边听一边录，听到有启发的观点说一句「这个有启发」，一期听完金句自动整理好——把「消费型听」变成「积累型听」</li><li><strong>语音日记/个人复盘</strong>：每天录一段语音回顾，哪些特别想记住的说一句「这个很重要」，AI 生成日记时会把你标记的内容作为重点——重点由你自己决定</li><li><strong>带娃记录</strong>：孩子突然说了句可爱的话，你正在忙没法掏手机，说一句「这句真可爱」就能记下来，等孩子长大这些就是最珍贵的回忆</li></ul><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><ul><li><strong>自定义口令词</strong>：支持设置最多 3 个口令词，每个口令词可指定不同的处理要求（如「帮我记一下」→ 捕捉知识点并总结，「这段不错」→ 提炼金句或精彩表达）</li><li><strong>实时识别</strong>：录音过程中 AI 实时监听口令词，无需手动操作</li><li><strong>智能处理</strong>：识别到口令词后，AI 自动对对应的录音内容按你设定的要求进行处理</li><li><strong>标记整合</strong>：口令词触发的处理结果统一展示在笔记的「标记」tab 中，同时在智能总结中重点标注，方便快速回顾</li></ul><h2 id="app端使用说明" tabindex="-1">APP端使用说明 <a class="header-anchor" href="#app端使用说明" aria-label="Permalink to &quot;APP端使用说明&quot;">​</a></h2><ol><li><p>打开 App，进入「我的账号」页面，在常用操作区域点击「语音口令」</p></li><li><p>进入语音口令设置页，开启「开启语音口令功能」开关</p></li><li><p>点击「添加口令词」，输入你想使用的口令词（如「帮我记一下」），并填写对应的处理要求（如「捕捉当下讲到的知识点并总结」）</p></li><li><p>最多可添加 3 个口令词，设置完成后即可生效</p></li><li><p>正常使用录音功能，录音过程中需要标记时，直接说出口令词即可——AI 会在生成笔记时自动识别并处理</p></li><li><p>录音结束后，进入笔记详情，在「标记」tab 中查看所有口令词触发的处理结果，智能总结中也会对这些内容做重点标注</p></li></ol><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+s+'" alt="语音口令入口" style="width:180px;border-radius:8px;"><img src="'+e+'" alt="开启功能" style="width:180px;border-radius:8px;"><img src="'+l+'" alt="添加口令词" style="width:180px;border-radius:8px;"><img src="'+n+'" alt="设置处理要求" style="width:180px;border-radius:8px;"><img src="'+d+'" alt="标记结果" style="width:180px;border-radius:8px;"><img src="'+p+'" alt="智能总结标注" style="width:180px;border-radius:8px;"></div>',12)])])}const A=i(c,[["render",m]]);export{f as __pageData,A as default};
